const counts = { high: 0, medium: 0, low: 0 };
for (const item of $input.all()) {
  const p = String(item.json.priority || 'low').toLowerCase();
  if (counts[p] === undefined) counts[p] = 0;
  counts[p] += 1;
}
return [{ json: { counts, total: $input.all().length } }];

const { counts, total } = $input.first().json;
const lines = [`*Daily ops digest* — ${total} open tickets`];
for (const [priority, count] of Object.entries(counts)) {
  lines.push(`• ${priority}: ${count}`);
}
return [{ json: { text: lines.join('\n') } }];
